		{
			migrationBuilder.Sql("""
				INSERT INTO public.drills ("name",description,duration,instructions,demo_link,"source",created_at,updated_at,drill_type_id,user_id,"key") VALUES
					 ('Step Back Drill','Builds proper load and weight transfer for a more powerful controlled swing.',10,'Hitters take a small step backward with their rear foot into their back hip before moving forward to swing. It teaches players how to properly load their weight into their glutes and prevents them from lunging at the ball. Creates a more powerful, controlled swing with better weight distribution.','https://youtu.be/AkwKO0J2SEM?si=GiNbRgc2_4797_eQ','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'da5ef9b6-4f6d-43b5-ba52-4482dacaca3d'::uuid),
					 ('Fall Forward Drill','Teaches hitters a smooth forward move and timing into a strong balanced stride.',8,'Players start with feet crossed (lead leg behind rear leg) and fall forward into their stride as they swing. Develops a smooth, aggressive, and controlled forward move toward the ball. Teaches proper timing and helps players maintain strong posture throughout their stride.','https://youtu.be/IyCE0hey7-I?si=-OALgEkdt0O26LzU','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'bbef483c-da1b-4c4b-8478-3590a86c6c95'::uuid),
					 ('Tee Work – Inside Pitch','Trains hitters to attack inside pitches with quick hands and strong contact.',10,'Hitters practice driving inside pitches by positioning the tee closer to the front hip. Builds the muscle memory to turn on inside fastballs without rolling over the ball. Critical for youth hitters who often get jammed and lose power.','https://www.youtube.com/watch?v=VFnCgmbNWHU','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'18a03ce5-e732-4431-8ab0-08922942846f'::uuid),
					 ('Tee Work – Outside Pitch','Builds plate coverage by teaching hitters to stay back and drive outside pitches.',10,'Hitters practice staying back and driving outside pitches the other way by positioning the tee at the back of the strike zone. Teaches plate coverage and using all fields. Prevents the common mistake of pulling off an outside pitch.','https://www.youtube.com/watch?v=VFnCgmbNWHU','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'95060ef9-fcac-463b-80ca-a2013db82a72'::uuid),
					 ('Soft Toss Drill','Improves hand-eye coordination bat path and consistent contact with angled tosses.',12,'A coach or partner tosses balls from the side at a slight angle while the hitter drives them into a net. One of the most versatile 1 drills — improves hand-eye coordination, bat path, and contact. Great for warming up the swing or focusing on a specific zone.','https://www.youtube.com/watch?v=rV3EQ5tHcNE','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'7dacb188-5f40-4e78-9e5b-e1d999be370e'::uuid),
					 ('One-Hand Bat Drill (Top Hand)','Develops top-hand strength and keeps hitters through the ball.',8,'Hitters take cuts using only their top hand on the bat. Isolates top-hand strength and teaches hitters to stay through the ball. Especially helpful for players who are casting or pulling off early.','https://www.youtube.com/watch?v=3lqJJSAyCEM','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'dd042060-0cb4-46cb-b54f-ecc8f4e49b6e'::uuid),
					 ('One-Hand Bat Drill (Bottom Hand)','Builds bottom-hand strength and improves directional control through the zone.',8,'Hitters take swings using only their bottom hand. Builds bottom-hand strength and teaches hitters to lead with their bottom hand through the zone. Improves directional 1 and contact quality.','https://www.youtube.com/watch?v=jyPcxGyxPhY','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'5ddcefb2-524f-46ae-ab2a-a9f006034e31'::uuid),
					 ('Live Batting Practice (Flips)','Provides game-like reps that build timing confidence and quality contact.',15,'Coach or player flips balls from 10–15 feet away while the hitter focuses on seeing the ball and making solid contact. One of the most game-realistic 1 reps you can get in practice. Builds confidence and timing.','https://www.youtube.com/watch?v=UpG4df0ivK4','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'ca78d9af-a726-4003-ae4e-006b3eecf796'::uuid),
					 ('High Tee Drill','Trains hitters to stay on top of the ball and reduce pop ups.',8,'The batting tee is positioned at the top of the strike zone. Forces hitters to stay on top of the ball and drive it down into the ground. A great cure for pop-up tendencies and upper-cutting swings.','https://www.youtube.com/watch?v=0BYiG_0saOY','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'218cbb7c-ae24-45bd-b282-ae32b820e9f8'::uuid),
					 ('Tracking Drill (No Swing)','Improves pitch recognition by having hitters track the ball to the zone without swinging.',8,'Coach or player throws or flips balls and the hitter tracks them all the way in without swinging — just catching the ball bare-handed. Sharpens pitch recognition and trains the eyes to stay on the ball from release point to contact zone.',NULL,'System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'59b2f22c-eee4-4dbc-99f9-98ce56feb543'::uuid);
				INSERT INTO public.drills ("name",description,duration,instructions,demo_link,"source",created_at,updated_at,drill_type_id,user_id,"key") VALUES
					 ('Contact Point Tee Series','Teaches inside middle and outside contact points for complete plate coverage.',12,'Three-tee station covering inside, middle, and outside contact points back-to-back. Players work all three in sequence, learning where to make contact based on pitch location. Builds full plate coverage and eliminates holes in the swing.','https://www.youtube.com/watch?v=KmtvdCoZwwU','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'20e4cd96-704e-4851-9fc8-f4baa497c4c1'::uuid),
					 ('Pepper Drill','Builds bat control hand speed and quick reactions with short controlled swings.',10,'Two to four fielders stand 10–15 feet away while a hitter makes controlled, short swings to drive the ball at them. Fielders field and toss back. Builds bat control, hand speed, and fun team energy. A classic for a reason.','https://www.youtube.com/watch?v=oPJkdOSpNHM','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',1,NULL,'f6c901f7-a7bd-4532-9026-fc0e00c0c606'::uuid),
					 ('Towel Drill','Reinforces extension follow-through and release point in the pitching delivery.',12,'Pitchers hold a small towel between their fingers while practicing their delivery toward a target. Focuses on extension, follow-through, and a consistent release point without the strain of throwing a real ball. Builds muscle memory for a long, linear delivery.','https://www.youtube.com/watch?v=-Ri-PVv4Urk','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'22cb7155-ed4b-4f1c-8bbe-04dd4cbb3803'::uuid),
					 ('Balance Point Drill','Improves pitching balance posture and sequencing at leg lift.',10,'Pitchers stop and hold at the balance point (leg lift) for 2–3 seconds before completing their delivery. Teaches proper posture, balance, and sequencing at the top of the delivery. A very common fix for control and mechanics issues.','https://www.youtube.com/watch?v=WAH4ttr8JUI','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'fcc90f0e-74d0-42b1-b2e9-1c40e84d5e50'::uuid),
					 ('K-Position Drill','Fixes arm path and elbow position by rehearsing proper release mechanics.',8,'Pitchers practice the throwing position at the release point — arm up, elbow at shoulder height, glove tucked — before completing the pitch. Identifies and corrects "short arming" and low elbow issues. Simple but high-impact mechanics drill.',NULL,'System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'47517442-c393-4176-97d1-d42a659efb6b'::uuid),
					 ('Flat Ground 2','Builds arm strength command and repeatable mechanics with lower stress throws.',15,'Pitchers throw at full or near-full intent from flat ground rather than a mound. Reduces strain while building arm strength, command, and repeatable mechanics. A staple of arm care and development programs.','https://www.youtube.com/watch?v=jbsP6U4y2B4','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'de5b1f97-5cb2-42c2-a75e-eddd586b1554'::uuid),
					 ('Two-Seam vs. Four-Seam Grip Drill','Teaches fastball grip differences that influence movement and accuracy.',10,'Pitchers practice finding and gripping both two-seam and four-seam fastball grips out of their glove, then throwing each into a net. Teaches grip fundamentals that affect ball movement and accuracy. Essential early-stage pitch education.','https://www.youtube.com/shorts/7WspIkR2AF8','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'e50f46be-53e4-47d1-9248-554c1a39704a'::uuid),
					 ('Pick-Off Move Drill (Right Handed)','Develops right-handed pick-off footwork timing and runner control.',10,'Pitchers practice stepping off the rubber and throwing to a base (first or second) with simulated runners. Teaches proper footwork, quick decision-making, and timing. Even youth pitchers should learn the basics of holding runners.','https://www.youtube.com/watch?v=7WThd8w7uDU','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'90322335-cae9-4a73-8a0e-52eb850327cc'::uuid),
					 ('Strike Zone Target Drill','Builds command and focus by attacking specific strike-zone quadrants.',12,'Pitchers throw at a strike zone target (taped on a net or a commercial target) focusing on 1 quadrants — up/down, inside/outside. Builds command and mental focus. Can compete (count pitches per quadrant) to add game pressure.','https://www.youtube.com/watch?v=98sKUDGi1P4','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'efc91f86-8e22-46cd-862c-da6225796e7a'::uuid),
					 ('2 Zone Accuracy','Improves throwing accuracy for youth pitchers through target-based reps.',10,'Excellent accuracy drills for 9-14 year olds.','https://www.youtube.com/watch?v=9tWZEBWuSco','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'7f305719-d40f-46a2-922d-80ecc5e47911'::uuid);
				INSERT INTO public.drills ("name",description,duration,instructions,demo_link,"source",created_at,updated_at,drill_type_id,user_id,"key") VALUES
					 ('Bullpen Session (15-Pitch)','Simulates game counts to develop command strategy and pressure execution.',15,'Pitchers throw a structured 15-pitch bullpen simulating game situations — first-pitch strikes, ahead/behind counts, full count. Teaches mental approach and command under pressure. Coach calls count before each pitch.','https://www.youtube.com/watch?v=dsWsjwduznw','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',2,NULL,'aa28a774-b79f-4eca-987d-fcd5cfbea2b1'::uuid),
					 ('Short Hop Drill','Improves glove presentation and low fielding technique on short hops.',8,'Two players face each other and throw short hops that bounce just in front of the fielder''s glove. Teaches players to keep hands out in front and stay low, improving ability to handle difficult bounces. Makes players more confident fielding ground balls in games.','https://www.youtube.com/watch?v=5eZk9wlK22c','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'3e126c45-aa0c-427c-aacc-192d8a6cd978'::uuid),
					 ('Slow Roller Drill','Trains infielders to charge slow rollers and throw accurately on the run.',10,'Coach rolls slow grounders toward the fielder, who must charge aggressively and make a quick, accurate throw. One of the hardest plays in infield — charging a slow roller with momentum toward first base. Builds confidence and explosiveness.','https://www.youtube.com/watch?v=0JzasbZpte4','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'874113cd-aa72-4f0c-82fb-a5299f8fb50d'::uuid),
					 ('Ground Ball Triangle Drill','Provides high-rep infield work for clean hands and quick exchanges.',10,'Three infielders stand in a triangle and roll/throw ground balls to each other, fielding and returning in sequence. High-rep, low-fatigue fielding drill that keeps everyone moving. Great for warm-up or fundamentals practice.','https://www.youtube.com/watch?v=q1ORurKURFw','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'2ccbf5a4-9173-4837-b4fc-1723cc03ff5d'::uuid),
					 ('Double Play Feed Drill (Flip)','Sharpens middle infield feed footwork and tosses for turning double plays.',10,'Middle infielders (2B and SS) practice the footwork and exchange for turning a double play — the flip or underhand toss to the bag. Focuses purely on the feed without a full ground ball, allowing high reps on the hardest part of the play.','https://www.youtube.com/watch?v=wras2d0dqv4','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'7413e393-a416-4f75-96ac-763d6006e50b'::uuid),
					 ('Backhand Drill','Develops backhand footwork glove work and off-balance throwing control.',10,'Fielders practice moving to their backhand side to field grounders in the hole or up the middle. Emphasizes the backhand glove position, footwork, and throwing off-balance. Common weak spot for youth infielders.','https://www.youtube.com/watch?v=uApXtyexsQI','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'00847aa7-b067-4a0e-a86a-7915532f352f'::uuid),
					 ('Forehand/Glove Side Drill','Improves glove-side range footwork and throw setup on forehand plays.',10,'Fielders practice moving to their glove side (forehand side) to field grounders hit toward the line. Focuses on footwork, glove angle, and staying through the ball to make the throw. Often neglected compared to backhand work.','https://www.youtube.com/watch?v=uApXtyexsQI','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'3410aa4e-d360-4291-9212-1330d2842752'::uuid),
					 ('First Step Quickness Drill','Trains explosive first-step reactions to improve infield range.',8,'Fielders start in a ready position. Coach randomly points left, right, or straight ahead, and players take their first step in that direction as fast as possible. Pure reaction training. A great way to start infield practice and wake up the feet.','https://www.youtube.com/watch?v=Iqq32zniXGg','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'834db449-98e8-4140-b7a3-2c7b5f27d7ff'::uuid),
					 ('Rapid Fire Ground Balls','Builds defensive endurance rhythm and reaction speed under pressure.',10,'Coach hits or rolls five consecutive ground balls at an infielder with only 3–4 seconds between each. Fielder works through all five, building endurance, rhythm, and quick reflexes. Simulates game-like stress.','https://www.youtube.com/watch?v=pwLbnJ6L-pQ','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'bc68f0b3-7d18-481f-ba96-79a5be499159'::uuid),
					 ('Throwing Footwork Drill','Automates infield throwing footwork patterns without ball handling distractions.',8,'Infielders practice only the footwork pattern for throwing — no glove, no ball. They simulate fielding a grounder and take the proper steps to set up their throw (crow hop or step-through). Isolates the footwork so it becomes automatic.','https://www.youtube.com/watch?v=HzqKlzNodIM','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'7bf65201-915e-42e1-a490-2eba085df933'::uuid);
				INSERT INTO public.drills ("name",description,duration,instructions,demo_link,"source",created_at,updated_at,drill_type_id,user_id,"key") VALUES
					 ('Pop Time Catcher to 2B Drill','Improves catcher transfer and throw speed to control the running game.',12,'Catcher receives a pitch, immediately comes up and throws to second base while a middle infielder covers. Times the throw and catch, simulating a stolen base attempt. Teaches the full play from receiving to transfer to throw.','https://www.youtube.com/watch?v=5No9AeOjGIk','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'8696cecb-129e-4f2c-ad89-508f366af28d'::uuid),
					 ('Around the Horn Drill','Builds infield throwing rhythm accuracy and team tempo after plays.',8,'After a play, infielders throw the ball around the infield (3B → 2B → SS → 1B → Catcher) quickly and crisply. Classic routine that builds team rhythm, accurate throws, and habit. A great energy-starter for fielding practice.','https://www.youtube.com/watch?v=swnvVgjOJXc','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'e2370c37-5969-47ae-b73d-00613f1cbc62'::uuid),
					 ('Drop Step Drill','Teaches outfielders to read and drop step quickly for balls over their heads.',12,'Outfielders practice a quick drop step (turning their body toward the ball) to run back and catch fly balls thrown over their heads. Helps players read the ball''s direction immediately. Prevents drifting and ensures readiness to make a strong throw after the catch.','https://www.youtube.com/watch?v=DEEtvyfdQAw','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'b2390af8-f5cd-42cb-a76c-73f78b1deffe'::uuid),
					 ('Crow Hop Throwing Drill','Builds outfield throwing power and momentum with proper crow hop mechanics.',10,'Outfielders practice the crow hop footwork (skip-step before throwing) to generate momentum and arm strength on throws to the infield. One of the most important outfield fundamentals. Many youth players don''t crow hop and it kills their arm strength.','https://www.youtube.com/watch?v=F2Noq_3ykb0','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'86f73150-1b0b-4120-931b-07a8bec2d58c'::uuid),
					 ('Communication Drill (Two-Outfielder)','Improves outfield communication to prevent collisions and secure catches.',10,'Two outfielders converge on a fly ball hit between them. One must call loudly for the ball while the other clears out. Teaches communication and collision prevention — one of the most important safety drills in outfield.','https://www.youtube.com/watch?v=7k_-2lRG8YY','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'e3627274-19d6-4641-a0d2-d9877c98d3b0'::uuid),
					 ('Angle Routes Drill','Teaches efficient diagonal routes to improve fly-ball range and positioning.',12,'Coach hits fly balls at angles requiring outfielders to run diagonal routes rather than straight back. Teaches proper route running — take the efficient angle, not the first instinct. Better routes mean more catches and better position for throws.','https://www.youtube.com/watch?v=ZlFWp5IQ1hs','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'f2b7503b-dd0d-4efa-a970-acbd627b5d10'::uuid),
					 ('Fence Drill (Wall Ball)','Builds safe confident fly-ball tracking and catches near the fence.',10,'Outfielders practice tracking fly balls near the warning track/fence by feeling for the fence with their non-glove hand before catching the ball. Teaches awareness, safety, and confidence near the wall.','https://www.youtube.com/watch?v=57ocvV9pHyE','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'6112a413-f008-476d-aa28-75e0f66475bf'::uuid),
					 ('Do-or-Die Charging Drill','Trains urgent outfield charges and quick home throws on scoring plays.',12,'Outfielders charge a single hit to the gap and must field and throw home quickly with a runner trying to score. Simulates the most pressure-filled outfield play. Teaches urgency, bare-hand options, and body positioning on the charge.','https://www.youtube.com/watch?v=cqsOIqnwJdk','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'75d550ab-e10b-4391-b8b2-57a0ac53d681'::uuid),
					 ('Line Drive Reads Drill','Sharpens first-read decisions on line drives to improve jump and catch success.',12,'Coach hits line drives at outfielders who must immediately read ball going up vs. coming down. Many youth players freeze on line drives — this drill trains the split-second read. One of the hardest skills in outfield.','https://www.youtube.com/watch?v=5FdTTWtIX9I','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'8d2d10a4-d78b-45fa-9b0e-e1f8e488ad4e'::uuid),
					 ('Relay / Cutoff Drill','Develops coordinated relay mechanics and communication on extra-base hits.',12,'Outfielder throws to a cutoff (infielder) who relays to a base. Teaches the full chain of communication and mechanics on extra-base hits. Outfielder, cutoff, and receiving base all have specific jobs.','https://www.youtube.com/watch?v=TJXQiYdueQc','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',4,NULL,'228dce7b-2254-4ad5-9a77-eee5b2bc1250'::uuid);
				INSERT INTO public.drills ("name",description,duration,instructions,demo_link,"source",created_at,updated_at,drill_type_id,user_id,"key") VALUES
					 ('Sacrifice Fly Drill','Teaches proper tag-up timing and explosive base running on caught fly balls.',10,'Runners practice tagging up at a base by waiting for a fly ball to be caught before sprinting to the next base. Emphasizes watching the ball into the fielder''s glove and reacting instantly. Proper tagging technique is essential for scoring runs on fly balls.','https://www.youtube.com/watch?v=5UBKMWNmqW4','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',3,NULL,'0e2edb02-aeb6-42e9-8378-b51a6b999c14'::uuid),
					 ('Primary Lead Drill','Builds correct primary lead distance balance and readiness off the bag.',8,'Runners practice taking the correct primary lead off first and second base — two shuffles away from the bag, balanced and ready. Teaches the proper stance and distance to maximize reaction time. The foundation of all baserunning.','https://www.youtube.com/watch?v=4_1yyhAaT_8','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',3,NULL,'acb095e0-74e7-4a8c-ae71-593ca4d2c4d6'::uuid),
					 ('Secondary Lead Drill','Improves secondary lead timing to gain extra bases on each pitch.',8,'Runners practice the secondary lead — moving with the pitcher''s release toward the next base to gain ground. Timed with a simulated pitch. A bigger secondary lead means scoring from second more often.','https://www.youtube.com/watch?v=9vypaId0IrM','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',3,NULL,'3b67321f-cde9-467f-ad4d-392a8268b0d9'::uuid),
					 ('First-to-Third Drill','Trains runners to read outfielders and take aggressive first-to-third opportunities.',12,'Runners practice reading a single to the outfield and running aggressively from first to third. Emphasizes reading the outfielder''s fielding position before rounding second. One of the highest-value baserunning plays.','https://www.youtube.com/watch?v=xuWeb8n2ktY','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',3,NULL,'41d6fc2d-e7f6-4bcc-836c-a8501c5c895b'::uuid),
					 ('Hit and Run Drill','Builds hitter and runner timing for effective hit-and-run execution.',12,'Batter swings at any pitch while the runner breaks for second on the pitch. Teaches hitter to protect the runner and runner to commit. Covers timing, communication, and situational awareness.','https://www.youtube.com/watch?v=0JKeF9btiHE','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',3,NULL,'8b05fa24-ec3f-48ca-a93b-7bddbd5f07b2'::uuid),
					 ('Sliding Drill (Pop-Up Slide)','Teaches a safe efficient pop-up slide for quick advancement after contact.',10,'Runners practice the pop-up slide (feet-first, popping up on contact to be ready to advance) at a base. Done on grass or a slide mat at slow speed. One of the safest and most useful slides in the game.','https://www.youtube.com/watch?v=yRqqQGQt9FU','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',3,NULL,'d6aed034-4823-48a7-8a87-e4053baf5e60'::uuid),
					 ('Steal of Second Drill','Develops steal mechanics timing and reads for successful second-base attempts.',12,'Runners practice the timing and route of stealing second base — primary lead, secondary lead, read the pitcher, go. Catcher and middle infielder respond to complete the play. Full-team teaching moment.','https://www.youtube.com/watch?v=82JaRX13TaY','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',3,NULL,'c69653f7-2d8b-4739-9440-7982281e92f2'::uuid),
					 ('Rounding Bases Drill','Improves base path efficiency and speed through proper rounding technique.',10,'Runners do a full circuit of the bases working on proper rounding technique — 1 the inside corner of each bag and leaning into the turns. Timed for competition. Teaches efficiency and hustle.','https://www.youtube.com/watch?v=07e1njau6gI','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',3,NULL,'6391778b-1768-4e80-9d19-a61907b4da2e'::uuid),
					 ('Dynamic Warm-Up Routine','Prepares players for practice by increasing mobility temperature and movement quality.',8,'Players move through a series of dynamic movements and stretches before picking up a ball. Raises heart rate, increases range of motion, and reduces injury risk. Should be done before every practice.','https://www.youtube.com/watch?v=2uWWXLCGFAM','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',6,NULL,'ea18c241-0e5a-4c84-921c-47bc4a409544'::uuid),
					 ('Arm Care Warm-Up (J-Band)','Activates shoulder stabilizers to prepare the arm for throwing safely.',5,'Players use resistance bands (J-Bands or similar) to activate the shoulder muscles before throwing. Includes internal/external rotation and arm circles with band tension. Standard pre-throw routine for arm health.','https://www.youtube.com/shorts/gQl4AxfSPkg','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',6,NULL,'cb770e27-4eab-49a1-aeaf-1efbdda1de82'::uuid);
				INSERT INTO public.drills ("name",description,duration,instructions,demo_link,"source",created_at,updated_at,drill_type_id,user_id,"key") VALUES
					 ('Partner Throwing Warm-Up','Gradually builds throwing intensity and arm readiness through progressive distance.',10,'Players pair up and begin throwing from 20 feet, gradually extending to 60–90 feet over 8–10 minutes. Classic warm-up that loosens the arm progressively and sets the tone for practice. Teach players to build distance slowly.','https://www.youtube.com/watch?v=UUyzef3uWXQ','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',6,NULL,'19fa69e2-4c1f-4e3d-bdbb-bc9887d036ed'::uuid),
					 ('Agility Ladder Drill','Improves foot speed coordination and athletic movement patterns.',8,'Players work through an agility ladder (or painted lines on the ground) with quick feet patterns — two-in, lateral shuffles, in-out patterns. Develops foot speed, coordination, and athleticism that transfers to all positions.','https://www.youtube.com/watch?v=SGetp1-TwKI','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',5,NULL,'7563c9ac-caf6-479b-b9f2-ac15310c0389'::uuid),
					 ('Cool-Down Stretch Routine','Promotes recovery flexibility and healthy post-practice habits.',8,'Cool down drills to promote  recovery, flexibility, and building healthy habits.','https://www.youtube.com/watch?v=f7qRzRHsr30','System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',5,NULL,'1e2db1b2-d6db-4183-8f0f-5f68fa46e207'::uuid),
					 ('Cool-Down Practice Recap','Reinforces key lessons and team culture during a structured closing huddle.',8,'Post practice recap is a good opportunity to cover what the players did well, one or two focus areas to reinforce before the next practice, any reminders or logistics and a closing huddle moment to build culture.',NULL,'System','2026-05-14 23:07:11.159','2026-05-14 23:07:11.159',5,NULL,'447d9b4e-17f1-4271-a48f-dc05181384fa'::uuid);
